def neighbors(self, r: int, c: int) -> list[tuple[int, int]]:
        """Return valid orthogonal and diagonal neighbors of (r, c)."""
        rows = len(self.grid)
        if rows == 0:
            return []
        cols = len(self.grid[0])
        result: list[tuple[int, int]] = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    result.append((nr, nc))
        return result

